python - <<'EOF'
import re,subprocess
p='design/gdd/adaptive-audio-and-tells.md'
new=open(p,encoding='utf-8').read().split('\n')
old=subprocess.run(['git','show','HEAD:'+p],capture_output=True).stdout.decode('utf-8').replace('\r\n','\n').split('\n')
def n(l): return len(re.findall(r'(?<!\\)\|',l))
oc={}
for l in old:
    if l.startswith('|'): oc[l[:40]]=n(l)
bad=0
for i,l in enumerate(new):
    if l.startswith('|') and l[:40] in oc and oc[l[:40]]!=n(l):
        print(i+1,l[:60],oc[l[:40]],n(l)); bad+=1
print('bad',bad)
EOF

